components.css:
.ds-status-cell {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 16px;
  font-weight: 600;
  padding: 3px 10px;
  border: 1px solid #37342b; /* board-rule */
  border-radius: 2px;
}
.ds-status-cell--pass { color: #4ade80; } /* pass-board */
.ds-status-cell--fail { color: #ff6f67; } /* fail-board */
.ds-status-cell--running { color: #e8b64a; } /* board-amber */
.ds-status-cell__glyph {
  width: 8px; height: 8px; border-radius: 50%;
  background: #e8b64a;
  animation: ds-pulse 1.8s ease-in-out infinite;
}
@keyframes ds-pulse { 50% { opacity: 0.35; } }
@media (prefers-reduced-motion: reduce) {
  .ds-status-cell__glyph { animation: none; }
}

.ds-stat-cell {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  border: 1px solid #37342b; /* board-rule */
  border-radius: 2px;
  color: #857f6a; /* bone-faint */
}
.ds-stat-cell__value {
  font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 16px;
  font-variant-numeric: tabular-nums;
  color: #efe8d4; /* bone */
}
.ds-stat-cell--compact { border: none; padding: 0; }

.ds-row {
  display: grid;
  grid-template-columns: 84px 160px minmax(90px,140px) minmax(0,1fr) 130px 100px 90px 90px 90px;
  align-items: baseline;
  gap: 16px;
  padding: 10px 18px;
  border-bottom: 1px solid #d8d2c0; /* paper-rule */
  text-decoration: none;
  color: #211e14; /* ink */
  font-family: Overpass, system-ui, 'Helvetica Neue', Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}
.ds-row:hover { background: #fcfaf4; } /* paper-raised: one tonal step */
.ds-mono { font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace; font-variant-numeric: tabular-nums; }
.ds-num { text-align: right; }
.ds-row__id { font-weight: 700; }
.ds-row__req { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #5f5948; } /* ink-dim */
.ds-row__remarks { color: #76705e; } /* ink-faint */
.ds-row__status--running { font-style: italic; color: #2545a8; } /* ballpoint */

.ds-bay {
  height: 92px;
  padding: 10px 12px;
  border: 1px solid #37342b; /* board-rule */
  border-radius: 2px;
  background: #1e1c17; /* board-raised */
  font-family: Overpass, system-ui, 'Helvetica Neue', Arial, sans-serif;
  color: #efe8d4; /* bone */
  overflow: hidden;
}
.ds-bay--running { border-color: #e8b64a; } /* board-amber: hue is the state */
.ds-bay--failed { border-color: #ff6f67; } /* fail-board */
.ds-bay--queued { border-style: dashed; background: transparent; }
.ds-bay--selected { outline: 2px solid #e8b64a; outline-offset: 1px; }
.ds-bay__head { display: flex; align-items: baseline; gap: 8px; }
.ds-bay__name { font-size: 17px; font-weight: 700; }
.ds-bay--running .ds-bay__name { color: #e8b64a; }
.ds-bay__dur { font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace; font-size: 16px; color: #96907c; } /* bone-dim */
.ds-bay__glyph { width: 8px; height: 8px; flex: none; }
.ds-bay__glyph--running { border-radius: 50%; background: #e8b64a; animation: ds-pulse 1.8s ease-in-out infinite; }
.ds-bay__desc { font-size: 16px; color: #96907c; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@keyframes ds-pulse { 50% { opacity: 0.35; } }
@media (prefers-reduced-motion: reduce) { .ds-bay__glyph--running { animation: none; } }

.ds-lane { width: 250px; font-family: Overpass, system-ui, sans-serif; color: #efe8d4; }
.ds-lane__top { display: flex; align-items: baseline; gap: 10px; }
.ds-lane__track {
  font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 16px; color: #857f6a; /* bone-faint */
}
.ds-lane__name { font-size: 17px; font-weight: 700; }
.ds-lane__model {
  font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 16px; color: #96907c; margin-top: 2px;
}
.ds-lane__meter { height: 6px; margin-top: 8px; background: #2a2820; } /* board-rule-soft */
.ds-lane__fill {
  display: block; width: 100%; height: 100%;
  background: #857f6a;
  transform-origin: left center;
  transition: transform 300ms ease;
}
.ds-lane__fill--live { background: #e8b64a; }

.ds-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.ds-tag {
  display: inline-flex; align-items: baseline; gap: 8px;
  padding: 2px 10px;
  border: 1px solid #2a2820; /* board-rule-soft */
  border-radius: 2px;
  background: #0c0b09; /* board-sunk */
  font-family: Overpass, system-ui, sans-serif;
  font-size: 16px;
  color: #efe8d4; /* bone */
}
.ds-tag__k { color: #857f6a; } /* bone-faint */

.ds-gate {
  display: flex; align-items: baseline; gap: 10px;
  padding: 8px 12px;
  border: 1px solid #37342b; /* board-rule */
  border-radius: 2px;
  background: #0c0b09; /* board-sunk */
  font-family: Overpass, system-ui, sans-serif;
  font-size: 16px;
  color: #efe8d4;
}
.ds-gate--fail { border-color: #ff6f67; } /* fail-board: the verdict is the hairline */
.ds-gate__mark { font-family: 'Overpass Mono', ui-monospace, monospace; }
.ds-gate--pass .ds-gate__mark { color: #4ade80; }
.ds-gate--fail .ds-gate__mark, .ds-gate--fail .ds-gate__meta { color: #ff6f67; }
.ds-gate__name { font-weight: 600; }
.ds-gate__meta { color: #96907c; margin-left: auto; font-family: 'Overpass Mono', ui-monospace, monospace; }

.ds-masthead {
  display: flex; align-items: center; gap: 10px;
  padding: 16px 28px 14px;
  border-bottom: 4px double #211e14; /* the printed masthead rule */
  font-family: Overpass, system-ui, sans-serif;
  color: #211e14;
}
.ds-masthead__mark { width: 26px; height: 26px; flex: none; }
.ds-masthead__brand {
  font-size: 17px; font-weight: 700; letter-spacing: 0.02em;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0;
}
.ds-masthead__live {
  margin-left: auto; flex: none;
  display: inline-flex; align-items: center; gap: 8px;
  font-family: 'Overpass Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 16px; color: #2545a8; /* ballpoint */
}
.ds-masthead__pip { width: 9px; height: 9px; background: #2545a8; } /* square on paper; round + pulsing on the board */
